/** A router link stand-in: a link that says it came through the router. */
const RouterLink = ({
  href,
  className,
  children,
}: LinkComponentProps): ReactElement => (
  <a className={className} data-router="" href={href}>
    {children}
  </a>
);

/** Render one node in the SVG it belongs to and return its root group. */
function renderNode(node: ReactElement): SVGGElement {
  const { container } = render(<svg aria-label="Graph">{node}</svg>);
  const root = container.querySelector("svg > g");
  if (!(root instanceof SVGGElement)) {
    throw new Error("the node rendered no SVG group");
  }
  return root;
}

